  const explicit = args[0] === '--python';
  if (explicit && (!args[1] || args[1].startsWith('--'))) throw new Error('Supply the selected Python executable after --python');
  const executable = explicit ? args.splice(0, 2)[1]
    : process.env.SF30_NDJSON_PYTHON || (process.platform === 'win32' ? 'python' : 'python3');
  const child = spawn(executable, [fileURLToPath(new URL('./cli.py', import.meta.url)), ...args], {
    stdio: 'inherit', shell: false, env: { ...process.env, SF30_XML_NODE: process.execPath },
  });
  const interrupt = () => child.kill('SIGINT');
  const terminate = () => child.kill('SIGTERM');
  process.on('SIGINT', interrupt);
  process.on('SIGTERM', terminate);
  try {
    const code = await new Promise((yes, no) => {
      child.once('error', () => no(new Error('Python 3.11+ is required; set SF30_NDJSON_PYTHON to its executable')));
      child.once('exit', (code, signal) => yes(code ?? (signal ? 130 : 1)));
    });
    process.exitCode = code;
  } finally {
    process.off('SIGINT', interrupt);
    process.off('SIGTERM', terminate);
  }
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => { console.error(`NDJSON dataset: ${error.message}`); process.exitCode = 1; });

"""MIT. Retained NDJSON workspace identity and managed original console startup."""
from __future__ import annotations
import hashlib
import os
from pathlib import Path
import stat
import sys

from application import InputError, json_bytes, load_json

SCHEMA = "stellar-forge.ndjson-managed-binding.v1"
STARTUP = "stellar-forge.ndjson-workspace-launch.v1"
SOURCE = Path(__file__).resolve().parents[1]
SOURCE_FILES = (
    "ndjson/application.py", "ndjson/cli.py", "ndjson/cli.mjs",
    "ndjson/ndjson_source.py", "ndjson/managed.py", "ndjson/merchant.mjs",
    "ndjson/public/index.html", "ndjson/public/app.js", "ndjson/public/style.css",
    "xml/xml_source.py", "xml/workspace.py", "xml/server.py", "xml/native.mjs",
    "dataset-handler.mjs",
)


def digest(data):
    return hashlib.sha256(data).hexdigest()


def regular(path, *, private=False, limit=None):
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or limit is not None and info.st_size > limit:
        raise InputError("Choose an original regular NDJSON workspace or source file: " + str(path))
    if private and os.name == "posix" and (info.st_uid != os.getuid() or info.st_mode & 0o077):
        raise InputError("NDJSON workspace metadata must remain private and operator-owned")
    return info


def source_digest(path):
    info = regular(path, limit=4 * 1024 * 1024)
    value = hashlib.sha256()
    with path.open("rb") as handle:
        opened = os.fstat(handle.fileno())
        if (opened.st_dev, opened.st_ino) != (info.st_dev, info.st_ino):
            raise InputError("Original NDJSON source changed while opening")
        for data in iter(lambda: handle.read(65536), b""):
            value.update(data)
        after = os.fstat(handle.fileno())
    if (after.st_size, after.st_mtime_ns, after.st_ctime_ns) != (
            info.st_size, info.st_mtime_ns, info.st_ctime_ns):
        raise InputError("Original NDJSON source changed while reading")
    return value.hexdigest()


def inspect_binding(directory):
    """Read saved identity without acquiring the original SQLite writer."""
    raw = Path(directory).expanduser().absolute()
    root = raw.resolve(strict=True)
    if raw != root or root.is_symlink():
        raise InputError("Choose the original absolute NDJSON workspace without path aliases")
    info = root.stat()
    if not stat.S_ISDIR(info.st_mode) or os.name == "posix" and (
            info.st_uid != os.getuid() or info.st_mode & 0o077):
        raise InputError("Choose the original private, operator-owned NDJSON workspace")
    marker = root / "workspace.json"
    marker_info = regular(marker, private=True, limit=4096)
    data = marker.read_bytes()
    if load_json(data) != {"schema": "stellar-forge.ndjson-workspace.v1"}:
        raise InputError("Choose a workspace initialized or received by the original NDJSON command")
    database = regular(root / "workspace.sqlite", private=True)
    for name in ("sources", "plans", "builds", "comparisons", "tmp"):
        item = root / name
        if item.is_symlink() or not item.is_dir():
            raise InputError("Original NDJSON storage directory is missing: " + name)
    if sys.version_info < (3, 11):
        raise InputError("The original NDJSON workspace requires Python 3.11 or newer")
    value = {
        "schema": SCHEMA, "workspace": str(root), "sourceRoot": str(SOURCE),
        "workspaceIdentity": {
            "device": str(info.st_dev), "inode": str(info.st_ino),
            "markerDevice": str(marker_info.st_dev), "markerInode": str(marker_info.st_ino),
            "markerSha256": digest(data),
            "databaseDevice": str(database.st_dev), "databaseInode": str(database.st_ino),
        },
        "python": {
            "executable": str(Path(sys.executable).absolute()), "prefix": sys.prefix,
            "basePrefix": sys.base_prefix, "implementation": sys.implementation.name,
            "version": list(sys.version_info[:3]),
        },
        "source": {name: source_digest(SOURCE / name) for name in SOURCE_FILES},
    }
    # Managed adoption copies the same source into its retained release.
    # Saved source rows and edition records remain mutable in the original database.
    bound = {key: item for key, item in value.items() if key != "sourceRoot"}
    return value | {"sha256": digest(json_bytes(bound))}


def require_binding(directory, expected):
    value = inspect_binding(directory)
    if expected is not None and (
            not isinstance(expected, str) or len(expected) != 64
            or any(char not in "0123456789abcdef" for char in expected)
            or expected != value["sha256"]):
        raise InputError("The selected NDJSON workspace, Python or original source changed; review this application again")
    return value


def startup(server, binding, connection_file=None):
    value = {
        "schema": STARTUP, "status": "NDJSON_WORKSPACE_READY",
        "workspace": binding["workspace"], "bindingSha256": binding["sha256"],
        "sourceRoot": binding["sourceRoot"], "python": binding["python"],
        "pid": os.getpid(), "console": server.url,
    }
    if connection_file is not None:
        value["connectionFile"] = connection_file
    return value

// MIT. Prepare and launch the original seller for a retained NDJSON dataset.
import { createHash } from 'node:crypto';
import { createReadStream } from 'node:fs';
import { readFile, writeFile, lstat } from 'node:fs/promises';
import { resolve, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { spawn } from 'node:child_process';

export { prepareNdjsonRelease, inspectNdjsonRelease } from './release.mjs';

const SCHEMA = 'stellar-forge.ndjson-merchant.v1';
const HASH = /^[a-f0-9]{64}$/;
const MAX_BYTES = 256 * 1024 * 1024;
const rootFiles = ['data.csv', 'dataset.json', 'ndjson-lineage.json', 'source.ndjson',
  'plan.json', 'payment.json', 'seller.json', 'openapi.json', 'OPERATING.md'];
const clientFiles = ['seller-client.mjs', 'seller-client.d.mts', 'seller-openapi.json',
  'package.json', 'README.md', 'client-export.json'].map(name => 'customer/' + name);
const files = [...rootFiles, ...clientFiles].sort();
const json = value => JSON.stringify(value, null, 2) + '\n';

async function jsonFile(path, maximum = 256 * 1024) {
  const info = await lstat(path);
  if (!info.isFile() || info.isSymbolicLink() || info.size > maximum) throw new Error('Invalid retained JSON file');
  const bytes = await readFile(path);
  if (bytes.length > maximum) throw new Error('Retained JSON exceeds its size limit');
  return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes));
}
async function fileIdentity(path) {
  const info = await lstat(path);
  if (!info.isFile() || info.isSymbolicLink() || info.size > MAX_BYTES) throw new Error('Invalid retained merchant file');
  let bytes = 0;
  const hash = createHash('sha256');
  for await (const chunk of createReadStream(path)) {
    bytes += chunk.length;
    if (bytes > MAX_BYTES) throw new Error('Merchant file exceeds 256 MiB');
    hash.update(chunk);
  }
  if (bytes !== info.size) throw new Error('Merchant file changed while being read');
  return { bytes, sha256: hash.digest('hex') };
}
async function write(path, value) {
  await writeFile(path, typeof value === 'string' ? value : json(value), { flag: 'wx', mode: 0o600 });
}
async function directory(input) {
  const path = resolve(input), info = await lstat(path);
  if (!info.isDirectory() || info.isSymbolicLink()) throw new Error('Use a retained real merchant directory');
  return path;
}

export async function prepareNdjsonMerchant({ prepared, origin, path = '/data' } = {}) {
  const root = await directory(prepared);
  const review = await jsonFile(join(root, 'ndjson-lineage.json'));
  if (review.schema !== 'stellar-forge.ndjson-build.v1' ||
      !HASH.test(review.source ?? '') || !HASH.test(review.plan ?? ''))
    throw new Error('Use the completed original NDJSON workspace export');
  for (const [name, expected] of [['source.ndjson', review.source], ['plan.json', review.plan],
      ['data.csv', review.files?.['data.csv']?.sha256], ['dataset.json', review.files?.['dataset.json']?.sha256]]) {
    if ((await fileIdentity(join(root, name))).sha256 !== expected) throw new Error('Retained source or projection changed: ' + name);
  }
  const [{ loadDatasetConfig }, { buildDatasetSellerConfig }, { compileSellerRoutes },
    { compileSellerOpenApi }, { exportSellerClient }] = await Promise.all([
    import('../dataset-handler.mjs'), import('../dataset-cli.mjs'), import('../resource-server.mjs'),
    import('../developer-portal.mjs'), import('../developer/client-export.mjs'),
  ]);
  const dataset = await loadDatasetConfig(join(root, 'dataset.json'));
  if (dataset.describe().snapshot !== review.native?.snapshot)
    throw new Error('Native dataset snapshot differs from its completed source review');
  const payment = await jsonFile(join(root, 'payment.json'), 16384);
  const seller = await buildDatasetSellerConfig(dataset, { payment, origin, path });
  const compiled = compileSellerRoutes(seller.routes.map(route => ({
    id: route.id, definition: { ...route.definition, url: seller.publicOrigin + route.path },
    handler: dataset.handle, admit: dataset.admit,
  })));
  const openapi = compileSellerOpenApi(compiled);
  await write(join(root, 'seller.json'), seller);
  await write(join(root, 'openapi.json'), openapi);
  const customer = await exportSellerClient({ openapi: join(root, 'openapi.json'), out: join(root, 'customer') });
  await write(join(root, 'OPERATING.md'), [
    '# NDJSON merchant and customer handoff', '',
    'This package contains the original JSON Lines export, reviewed mapping, native CSV dataset, seller configuration and generated customer SDK.',
    'Keep this whole directory private. Only the configured dataset route and the original seller metadata belong on the public ingress.', '',
    '## Start the original seller', '',
    'From the installed toolkit, run:',
    '~~~sh',
    'starforge dataset-ndjson-merchant status --prepared /absolute/merchant',
    'starforge dataset-ndjson-merchant serve --prepared /absolute/merchant --port 8423',
    '~~~',
    'The second command opens the original challenge-only seller and developer page. Configure the original native x402 dependencies and add --facilitator with the actual operator-selected URL for native settlement. The original --allow-local-facilitator, --max-in-flight, --drain-grace-ms and --availability-dir controls remain available.',
    'Use the printed health and developer URLs. Customer files are in customer/; begin with its original README.md. This prepared OpenAPI describes the challenge-only configuration. The running seller exposes its actual native mode through /_seller/openapi.json.', '',
    '## Recover or prepare a new edition', '',
    'Reopen this package with status before launch. It checks the complete file manifest and loads the same original dataset engine.',
    'To restore the source workspace, initialize a new NDJSON workspace, import source.ndjson with its source command, save plan.json with its plan command, then build the returned source and mapping IDs. The resulting build ID and native snapshot must equal ndjson-lineage.json.',
    'The original source project ZIP from the NDJSON workspace supports this reconstruction through its single import command.',
    'A new source edition uses the same retained mapping. Inspect its keyed comparison before preparing a new merchant directory. Existing merchant releases and buyer operations keep their original paths, selected terms and intent IDs.', '',
    '## Selected source', '',
    'Source SHA-256: ' + review.source,
    'Mapping SHA-256: ' + review.plan,
    'Build: ' + review.id,
    'Native dataset snapshot: ' + dataset.describe().snapshot,
    'Public origin: ' + seller.publicOrigin,
    'Resource: ' + seller.publicOrigin + path,
    'Rows: ' + dataset.describe().rowCount, '',
    'Native amounts remain exact atomic-unit strings in payment.json. One original paid request retrieves one dataset page; continue the original returned cursor without changing its filters or selected fields.', '',
  ].join('\n'));
  const identities = {};
  for (const name of files) identities[name] = await fileIdentity(join(root, name));
  const manifest = { schema: SCHEMA, state: 'PREPARED', source: review.source, plan: review.plan,
    build: review.id, snapshot: dataset.describe().snapshot, origin: seller.publicOrigin,
    resource: seller.publicOrigin + path, files: identities,
    customer: { manifest: customer.manifest, filesSha256: customer.filesSha256 } };
  await write(join(root, 'merchant.json'), manifest);
  return { directory: root, ...manifest };
}

export async function inspectNdjsonMerchant({ prepared } = {}) {
  const root = await directory(prepared);
  const manifest = await jsonFile(join(root, 'merchant.json'));
  if (manifest.schema !== SCHEMA || manifest.state !== 'PREPARED' ||
      !HASH.test(manifest.snapshot ?? '') || !manifest.files ||
      Object.keys(manifest.files).sort().join('\0') !== files.join('\0'))
    throw new Error('Incomplete or unsupported NDJSON merchant package');
  for (const name of files) {
    const actual = await fileIdentity(join(root, name)), expected = manifest.files[name];
    if (!expected || actual.bytes !== expected.bytes || actual.sha256 !== expected.sha256)
      throw new Error('Retained merchant file changed: ' + name);
  }
  const { loadDatasetConfig } = await import('../dataset-handler.mjs');
  const dataset = await loadDatasetConfig(join(root, 'dataset.json'));
  if (dataset.describe().snapshot !== manifest.snapshot) throw new Error('Native dataset snapshot changed');
  const seller = await jsonFile(join(root, 'seller.json'));
  if (seller.publicOrigin !== manifest.origin || seller.routes?.length !== 1 ||
      seller.publicOrigin + seller.routes[0].path !== manifest.resource)
    throw new Error('Merchant route differs from the original prepared package');
  return { directory: root, ...manifest, dataset: dataset.describe() };
}

async function originalSeller(root, args) {
  if (args.includes('--config') || args.includes('--handlers'))
    throw new Error('The prepared package supplies its original config and dataset handlers');
  const child = spawn(process.execPath, [
    fileURLToPath(new URL('../serve.mjs', import.meta.url)),
    '--config', join(root, 'seller.json'),
    '--handlers', fileURLToPath(new URL('../examples/dataset-application.mjs', import.meta.url)), ...args,
  ], { shell: false, stdio: 'inherit',
    env: { ...process.env, SF30_DATASET_CONFIG: join(root, 'dataset.json') } });
  const stop = signal => child.kill(signal);
  const interrupt = () => stop('SIGINT'), terminate = () => stop('SIGTERM');
  process.on('SIGINT', interrupt); process.on('SIGTERM', terminate);
  try {
    process.exitCode = await new Promise((done, fail) => {
      child.once('error', fail);
      child.once('exit', (code, signal) => done(code ?? (signal ? 130 : 1)));
    });
  } finally { process.off('SIGINT', interrupt); process.off('SIGTERM', terminate); }
}

export async function main(args = process.argv.slice(2)) {
  if (args.includes('--help')) {
    console.log('NDJSON merchant:\n  status --prepared DIRECTORY\n  serve --prepared DIRECTORY [original seller options]\n  prepare --prepared WORKSPACE_EXPORT --origin HTTPS_ORIGIN [--path /data]\n  release-package --prepared DIRECTORY --dataset-directory DIRECTORY --out DIRECTORY\n  release-status --package DIRECTORY');
    return;
  }
  const [command, ...rest] = args;
  if (command === 'release-status') {
    if (rest.length !== 2 || rest[0] !== '--package' || !rest[1] || rest[1].startsWith('--'))
      throw new Error('release-status requires --package DIRECTORY');
    const { inspectNdjsonRelease } = await import('./release.mjs');
    console.log(json(await inspectNdjsonRelease({ directory: rest[1] }))); return;
  }
  if (!['prepare', 'status', 'serve', 'release-package'].includes(command))
    throw new Error('Choose prepare, status, serve, release-package or release-status; use --help');
  const index = rest.indexOf('--prepared');
  if (index < 0 || !rest[index + 1] || rest[index + 1].startsWith('--') || rest.lastIndexOf('--prepared') !== index)
    throw new Error('Supply one --prepared directory');
  const prepared = rest[index + 1]; rest.splice(index, 2);
  if (command === 'serve') {
    const current = await inspectNdjsonMerchant({ prepared });
    return originalSeller(current.directory, rest);
  }
  if (command === 'status') {
    if (rest.length) throw new Error('status accepts only --prepared');
    console.log(json(await inspectNdjsonMerchant({ prepared }))); return;
  }
  const options = {}, allowed = command === 'release-package'
    ? ['--dataset-directory', '--out'] : ['--origin', '--path'];
  for (let i = 0; i < rest.length; i += 2) {
    const flag = rest[i];
    if (!allowed.includes(flag) || options[flag] !== undefined ||
        !rest[i + 1] || rest[i + 1].startsWith('--')) throw new Error('Invalid merchant preparation options');
    options[flag] = rest[i + 1];
  }
  if (command === 'release-package') {
    if (!options['--dataset-directory'] || !options['--out'])
      throw new Error('release-package requires --dataset-directory and --out');
    const { prepareNdjsonRelease } = await import('./release.mjs');
    console.log(json(await prepareNdjsonRelease({ prepared,
      datasetDirectory: options['--dataset-directory'], outputDirectory: options['--out'] }))); return;
  }
  if (!options['--origin']) throw new Error('--origin is required');
  console.log(json(await prepareNdjsonMerchant({ prepared, origin: options['--origin'], path: options['--path'] })));
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error => { console.error('NDJSON merchant: ' + error.message); process.exitCode = 1; });

"""MIT. Lossless JSON Lines inventory and projection into the original SF30 dataset ABI."""
from __future__ import annotations

from decimal import Decimal, InvalidOperation
import json
import math
import re
from typing import BinaryIO, Callable, Any

from xml_source import InputError, MAX_SOURCE

SCHEMA = "stellar-forge.ndjson-mapping.v1"
MAX_RECORD = 16 * 1024 * 1024
MAX_DEPTH = 64
MAX_PATHS = 4096
NAME = re.compile(r"[A-Za-z][A-Za-z0-9_]{0,47}\Z")
INT = re.compile(r"-?(0|[1-9][0-9]*)\Z")
NUMBER = re.compile(r"-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?\Z")
MISSING = object()


class JsonNumber(str):
    """Keep the source JSON numeric token, including exponent and trailing zeros."""


def utf16_length(value: str) -> int:
    try:
        return len(value.encode("utf-16-le")) // 2
    except UnicodeError as error:
        raise InputError("JSON strings must contain valid Unicode scalar values") from error


def exact_json(value: Any) -> str:
    """Serialize parsed JSON while retaining every original numeric lexeme."""
    if isinstance(value, JsonNumber):
        return str(value)
    if value is None:
        return "null"
    if value is True:
        return "true"
    if value is False:
        return "false"
    if isinstance(value, str):
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, list):
        return "[" + ",".join(exact_json(item) for item in value) + "]"
    if isinstance(value, dict):
        return "{" + ",".join(json.dumps(key, ensure_ascii=False) + ":" + exact_json(item)
                              for key, item in value.items()) + "}"
    raise InputError("Expected an original JSON value")


def _pairs(items):
    result = {}
    for key, value in items:
        if key in result:
            raise InputError(f"Duplicate JSON member: {key[:80]}")
        result[key] = value
    return result


def _constant(_):
    raise InputError("Non-finite JSON numbers are not accepted")


def _validate_tree(value, depth=0):
    if depth > MAX_DEPTH:
        raise InputError("JSON exceeds 64 levels of nesting")
    if isinstance(value, str):
        utf16_length(value)
    elif isinstance(value, dict):
        for key, item in value.items():
            utf16_length(key)
            _validate_tree(item, depth + 1)
    elif isinstance(value, list):
        for item in value:
            _validate_tree(item, depth + 1)


def records(stream: BinaryIO, stats: dict | None = None):
    """Read one physical record at a time; blank lines are counted and retained."""
    stats = stats if stats is not None else {}
    stats.update(bytes=0, physicalLines=0, records=0, blankLines=0, utf8Bom=False, maxRecordBytes=0)
    while raw := stream.readline(MAX_RECORD + 1):
        stats["bytes"] += len(raw)
        stats["physicalLines"] += 1
        line = stats["physicalLines"]
        if stats["bytes"] > MAX_SOURCE:
            raise InputError("NDJSON source exceeds 256 MiB")
        if len(raw) > MAX_RECORD:
            raise InputError(f"Line {line}: record exceeds 16 MiB")
        stats["maxRecordBytes"] = max(stats["maxRecordBytes"], len(raw))
        if line == 1 and raw.startswith(b"\xef\xbb\xbf"):
            stats["utf8Bom"] = True
            raw = raw[3:]
        try:
            text = raw.decode("utf-8", errors="strict")
            if not text.strip():
                stats["blankLines"] += 1
                continue
            value = json.loads(text, parse_int=JsonNumber, parse_float=JsonNumber,
                               parse_constant=_constant, object_pairs_hook=_pairs)
            if not isinstance(value, dict):
                raise InputError("Each nonblank line must contain one JSON object")
            _validate_tree(value)
        except (UnicodeError, json.JSONDecodeError, RecursionError) as error:
            detail = f"column {error.colno}: {error.msg}" if isinstance(error, json.JSONDecodeError) else str(error)
            raise InputError(f"Line {line}: invalid UTF-8 JSON object ({detail})") from error
        except InputError as error:
            raise InputError(f"Line {line}: {error}") from error
        stats["records"] += 1
        yield line, value


def kind(value):
    if isinstance(value, JsonNumber):
        return "integer" if INT.fullmatch(value) else "number"
    if value is None:
        return "null"
    if type(value) is bool:
        return "boolean"
    if isinstance(value, str):
        return "string"
    if isinstance(value, list):
        return "array"
    return "object"


def inventory(stream: BinaryIO) -> dict:
    stats, paths = {}, {}
    metadata_bytes = 0

    def visit(value, path, seen):
        nonlocal metadata_bytes
        if path not in paths:
            if len(paths) >= MAX_PATHS:
                raise InputError("Source has more than 4096 distinct field paths; use a narrower export")
            metadata_bytes += len(json.dumps(path, ensure_ascii=False).encode("utf-8")) + 256
            paths[path] = {"path": list(path), "occurrences": 0, "records": 0, "types": {}, "samples": []}
        item = paths[path]
        item["occurrences"] += 1
        if path not in seen:
            item["records"] += 1
            seen.add(path)
        value_kind = kind(value)
        item["types"][value_kind] = item["types"].get(value_kind, 0) + 1
        if isinstance(value, dict):
            for key, child in value.items():
                visit(child, path + (key,), seen)
        elif isinstance(value, list):
            for child in value:
                visit(child, path + (None,), seen)
        elif len(item["samples"]) < 3:
            sample = {"type": value_kind, "json": exact_json(value)[:180]}
            if sample not in item["samples"]:
                item["samples"].append(sample)
                metadata_bytes += len(json.dumps(sample, ensure_ascii=False).encode("utf-8"))
        if metadata_bytes > 8 * 1024 * 1024:
            raise InputError("Source field inventory exceeds 8 MiB; use a narrower export")

    for _, value in records(stream, stats):
        visit(value, (), set())
    return {"schema": "stellar-forge.ndjson-inventory.v1", **stats,
            "arrayPathMarker": "A null path segment describes all array elements; mappings use a concrete integer index.",
            "paths": list(paths.values())}


def exact_keys(value, allowed, label):
    if not isinstance(value, dict) or set(value) - allowed:
        raise InputError(f"Invalid {label} fields")
    return value


def integer(value, low, high, label):
    if type(value) is not int or not low <= value <= high:
        raise InputError(f"{label} must be an integer from {low} to {high}")
    return value


def path_array(value, label):
    if not isinstance(value, list) or len(value) > MAX_DEPTH:
        raise InputError(f"{label} must be an array of exact object keys and array indexes")
    for segment in value:
        if isinstance(segment, str):
            if utf16_length(segment) > 2048:
                raise InputError(f"{label} contains a key longer than 2048 characters")
        elif type(segment) is not int or not 0 <= segment <= 1000000:
            raise InputError(f"{label} contains an invalid array index")
    return list(value)


def validate_plan(raw: dict) -> dict:
    exact_keys(raw, {"schema", "name", "recordPath", "columns", "filters", "ranges", "sorts",
                     "keys", "defaultLimit", "maxLimit", "maxBytes", "maxRows", "maxCellChars",
                     "allowEmpty"}, "NDJSON mapping")
    if raw.get("schema") != SCHEMA:
        raise InputError(f"Mapping schema must be {SCHEMA}")
    name = raw.get("name")
    if not isinstance(name, str) or not name.strip() or utf16_length(name) > 128 or re.search(r"[\x00-\x1f\x7f]", name):
        raise InputError("Dataset name must be printable text, 1–128 UTF-16 code units")
    columns = raw.get("columns")
    if not isinstance(columns, list) or not 1 <= len(columns) <= 64:
        raise InputError("Choose 1–64 exposed columns")
    result = {"schema": SCHEMA, "name": name, "recordPath": path_array(raw.get("recordPath", []), "recordPath"),
              "columns": [], "allowEmpty": raw.get("allowEmpty", False)}
    if type(result["allowEmpty"]) is not bool:
        raise InputError("allowEmpty must be an explicit boolean")
    names = set()
    for original in columns:
        exact_keys(original, {"name", "path", "type", "nullable", "mode", "missing"}, "column")
        key = original.get("name")
        if not isinstance(key, str) or not NAME.fullmatch(key) or key in names or key in {"constructor", "prototype", "__proto__"}:
            raise InputError("Column names must be unique SF30 identifiers")
        names.add(key)
        c = {"name": key, "path": path_array(original.get("path", []), f"{key}.path"),
             "type": original.get("type", "string"), "nullable": original.get("nullable", False),
             "mode": original.get("mode", "scalar"), "missing": original.get("missing", "error")}
        if c["type"] not in {"string", "integer", "number", "boolean"} or type(c["nullable"]) is not bool:
            raise InputError(f"{key}: select an original SF30 type and an explicit nullable flag")
        if c["mode"] not in {"scalar", "json", "state"} or c["missing"] not in {"error", "null"}:
            raise InputError(f"{key}: invalid projection mode or missing-value policy")
        if c["mode"] in {"json", "state"} and (c["type"] != "string" or c["nullable"]):
            raise InputError(f"{key}: JSON and state projections require a nonnullable string column")
        if c["mode"] == "scalar" and c["missing"] == "null" and not c["nullable"]:
            raise InputError(f"{key}: missing=null requires a nullable scalar column")
        result["columns"].append(c)
    state_paths = {tuple(c["path"]) for c in result["columns"] if c["mode"] == "state"}
    for c in result["columns"]:
        if c["mode"] != "state" and c["missing"] == "null" and tuple(c["path"]) not in state_paths:
            raise InputError(f"{c['name']}: add a state column for this path before mapping missing values to null")
