    '), sf30_export_budget AS MATERIALIZED (SELECT sf30_extract.*, (' + bytes + ') > ' +
    limits.maxRowBytes + ' AS ' + quote(flag) + ' FROM sf30_extract)\nSELECT ' +
    names.map(name => 'CASE WHEN ' + quote(flag) + ' THEN NULL ELSE ' + name + ' END AS ' + name).join(', ') +
